<script lang="ts">
  import { page } from '$app/state';
  import { goto } from '$app/navigation';
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  let kind = $state(page.url.searchParams.get('kind') === 'officers' ? 'officers' : 'charities');
  let letter = $state((page.url.searchParams.get('letter') ?? 'A').toUpperCase());
  let sort = $state(['most','least'].includes(page.url.searchParams.get('sort') ?? '') ? page.url.searchParams.get('sort')! : 'az');
  let results = $state<any[]>([]); let loading = $state(true);
  async function load() { loading=true; const r=await fetch(`/api/directory?kind=${kind}&letter=${letter}&sort=${sort}`); const p=await r.json(); results=p.results??[]; loading=false; }
  function choose(nextKind:string,nextLetter:string,nextSort=sort){kind=nextKind;letter=nextLetter;sort=nextSort;goto(`/directory?kind=${kind}&letter=${letter}&sort=${sort}`,{replaceState:true,noScroll:true});load();}
  $effect(()=>{ load(); });
</script>
<svelte:head><title>{kind === 'officers' ? 'Charity Officers' : 'Charities'} · NZ Connections</title></svelte:head>
<header><a href="/">← NZ Connections</a><a href="/explore">Search records</a></header>
<main><div class="eyebrow">PUBLIC RECORD DIRECTORY</div><h1>{kind === 'officers' ? 'Charity Officers' : 'Charities'}</h1><p>Browse imported Charities Register records alphabetically.</p>
  <div class="switch"><button class:active={kind==='charities'} onclick={()=>choose('charities',letter)}>Charities</button><button class:active={kind==='officers'} onclick={()=>choose('officers',letter)}>Charity Officers</button></div>
  <nav class="alphabet" aria-label="Alphabetical directory">{#each letters as l}<button class:active={letter===l} onclick={()=>choose(kind,l)}>{l}</button>{/each}</nav>
  <div class="toolbar"><div class="count">{loading?'LOADING…':`${results.length} RECORDS BEGINNING WITH ${letter}`}</div><label>Sort <select value={sort} onchange={(e)=>choose(kind,letter,e.currentTarget.value)}><option value="az">A–Z</option><option value="most">Most connections</option><option value="least">Least connections</option></select></label></div>
  <section>{#each results as e}<a class="row" href={`/record/${e.id}`}><div><strong>{e.canonical_name}</strong><span>{e.entity_type.replace('_',' ')}{e.status?` · ${e.status}`:''}{e.nzbn?` · NZBN ${e.nzbn}`:''}</span></div><div class:connected={Number(e.relationship_count)>0} class="connections" title={`${e.relationship_count ?? 0} recorded connections`}>{e.relationship_count ?? 0}</div><span class="open">View →</span></a>{/each}{#if !loading&&results.length===0}<div class="empty">No imported records beginning with {letter}.</div>{/if}</section>
</main>
