round:#0d2a20;color:#63e8aa}.open{color:#4de1a1!important}.empty{padding:40px 5px;color:#71867e}@media(max-width:600px){h1{font-size:38px}.open{display:none}.row{grid-template-columns:1fr auto}.toolbar{align-items:flex-start;flex-direction:column}}</style>